        {
            "bridges": config["bridges"],
            "links": config["links"],
            "delay": config["delay"],
            "bridge": config["bridge"],
            "ports": config["ports"],
            "age": config["age"],
        }
    )
    storm = config["storm"]
    if not isinstance(storm, dict) or frozenset(storm) != STORM_KEYS:
        raise InvalidInput("bad storm")
    window = storm["window"]
    limits = storm["limits"]
    move_limit = storm["move_limit"]
    hold = storm["hold"]
    for name, value in (
        ("window", window),
        ("move_limit", move_limit),
